using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.DTOs;
namespace OrcaFacil.Web.Pages.Dashboard; [Authorize] public class IndexModel:PageModel{private readonly ICurrentUserService _current; private readonly IDashboardQueries _queries; public DashboardDto? Dashboard{get;private set;} public IndexModel(ICurrentUserService current,IDashboardQueries queries){_current=current;_queries=queries;} public async Task OnGetAsync(CancellationToken ct)=>Dashboard=await _queries.GetDashboardAsync(_current.UserId,ct);}
